import './workbench.css';
import { zh as T,labels } from './zh.js';
import { clone,uid,catalog,styles,createProject,itemFrom,roomFrom,activeScheme,transformItems,groupItems,duplicateItems,templateFromItems,insertTemplate,updateRoomGeometry,serializeProject,importProject,validateProject,ProjectHistory } from './model.js';
import { examples,exampleProject,builtInTemplates,needPresets } from './examples.js';
import { runChecks,newRule,requirementStatus,ruleTypes } from './rules.js';
import { openDatabase,download,makeBackup,validateTemplate } from './storage.js';
