import { esc,createReport } from './report.js';
import { icon } from './icons.js';
let project,store,personalTemplates=[],projectCache=new Map(),selection=[],leftTab='spaces',rightTab='properties',mode='2d',tool='select',grid=true,snapping=true,isolatedGroup=null,editBase=null,drawPoints=[],overlay=null,saveTimer,saveChain=Promise.resolve(),saveStatus='saved',lastSavedRevision=-1,three=null,threeModule=null,dialogCleanup=null,mobilePanel=null,polygonEdit=false;
const history=new ProjectHistory(),builtins=builtInTemplates();
const $=s=>document.querySelector(s),scheme=()=>activeScheme(project),geometry=()=>scheme().geometry,currentStyle=()=>project.styles.find(s=>s.id===project.activeStyleId)??styles[0];
const button=(action,text,ico='',cls='',extra='')=>`<button type="button" aria-label="${esc(text)}" data-action="${action}" class="${cls}" ${extra}>${ico?icon(ico):''}<span>${text}</span></button>`;
const tiny=(action,label,ico,extra='')=>`<button type="button" data-action="${action}" class="icon-button" title="${esc(label)}" aria-label="${esc(label)}" ${extra}>${icon(ico)}</button>`;
const option=(value,text,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(text)}</option>`;
const field=(label,key,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input data-field="${key}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const selectField=(label,key,options,current)=>`<label class="field"><span>${label}</span><select data-field="${key}">${options.map(([v,t])=>option(v,t,current)).join('')}</select></label>`;
const textArea=(label,key,value)=>`<label class="field"><span>${label}</span><textarea data-field="${key}" rows="3">${esc(value??'')}</textarea></label>`;
const numberField=(label,key,value,min=-100000,max=100000)=>field(label,key,Math.round((value??0)*100)/100,'number',`step="any" min="${min}" max="${max}"`);
const collection=kind=>({item:'items',zone:'zones',structure:'structures',dimension:'dimensions'})[kind];
const selectedObjects=()=>selection.map(s=>({...s,object:geometry()[collection(s.kind)].find(o=>o.id===s.id)})).filter(s=>s.object);
const selectedItems=()=>selectedObjects().filter(s=>s.kind==='item').map(s=>s.object);
const selectedGroup=()=>scheme().groups.find(g=>selection.length===g.itemIds.length&&g.itemIds.every(id=>selection.some(s=>s.id===id)));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function guarded(fn){return async(...args)=>{try{return await fn(...args);}catch(e){console.error(e);toast(e.message?.match(/[\u4e00-\u9fff]/)?e.message:T.error);}};}
function editable(){if(scheme().protected){toast(T.protectedHint);return false;}return true;}
function markChanged(){project.revision++;project.updatedAt=new Date().toISOString();for(const s of project.schemes)if(s.check)s.check.stale=true;overlay=null;projectCache.set(project.id,clone(project));saveStatus='unsaved';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveNow(),650);}
function mutate(fn,{needs=false,protect=true}={}){if(protect&&!editable())return false;const before=clone(project);try{fn(project,scheme(),geometry());if(JSON.stringify(project)===JSON.stringify(before))return false;validateProject(project);if(needs){project.needs.revision++;}history.commit(before,project);markChanged();renderAll();return true;}catch(e){project=before;renderAll();toast(e.message?.match(/[\u4e00-\u9fff]/)?e.message:T.invalidNumber);return false;}}
async function saveNow(){clearTimeout(saveTimer);if(!project)return;const snapshot=clone(project);saveStatus='saving';renderHeader();saveChain=saveChain.catch(()=>{}).then(async()=>{try{if(!store)throw Error(T.storageUnavailable);await store.saveProject(snapshot);projectCache.set(snapshot.id,snapshot);if(project.id===snapshot.id&&project.revision===snapshot.revision){lastSavedRevision=snapshot.revision;saveStatus='saved';renderHeader();}}catch(e){saveStatus='saveFailed';renderHeader();toast(T.saveFailed);throw e;}});await saveChain.catch(()=>{});}
function renderHeader(){if(!project)return;const s=scheme();$('#topbar').innerHTML=`<div class="brand-mark">${icon('plan',25)}<strong>${T.brand}</strong><span class="brand-divider"></span><span class="local-label">${T.local}</span></div><div class="project-heading">${button('projects',esc(project.name),'folder','project-switch')}<span class="save-state ${saveStatus==='saveFailed'?'error':''}" role="status"><i></i>${T[saveStatus]}${saveStatus==='saveFailed'?` <button data-action="save">${T.retry}</button>`:''}</span></div><div class="header-actions">${tiny('help',T.help,'help')}${button('export',T.export,'export','primary small')}</div>`;
 $('#commandbar').innerHTML=`<div class="scheme-controls"><span class="eyebrow">${T.layout}</span><select id="scheme-select" aria-label="${T.layout}">${project.schemes.map(s=>option(s.id,s.name+(s.protected?' · '+T.protected:''),project.activeSchemeId)).join('')}</select>${tiny('schemes',T.addScheme,'copy')}${button('compare',T.compare,'','text-button')}</div><div class="history-controls">${tiny('undo',T.undo,'undo',history.past.length?'':'disabled')}${tiny('redo',T.redo,'redo',history.future.length?'':'disabled')}<span class="toolbar-divider"></span><div class="view-switch" role="group" aria-label="${T.view??T.scene3d}">${button('view2d',T.plan2d,'plan',mode==='2d'?'active':'')}${button('view3d',T.scene3d,'cube',mode!=='2d'?'active':'')}</div>${button('walk',three?.walking?T.exitWalk:T.walk,'walk','walk-button')}</div>`;
}
function renderLeft(){const g=geometry();$('#left-tabs').innerHTML=[['spaces','plan'],['furniture','sofa'],['templates','template']].map(([key,ico])=>button(`left-${key}`,T[key],ico,leftTab===key?'active':'')).join('');let content='';
 if(leftTab==='spaces'){
  content=`<div class="panel-heading"><div><span class="eyebrow">${T.spaces}</span><h2>${T.structuresTitle}</h2></div><span class="count">${g.zones.length}</span></div><div class="add-space-actions">${button('add-room',T.addRoom,'plus')}${button('draw-room',T.drawRoom,'plan')}${button('import-plan',T.importPlan,'image')}${button('measure',T.addMeasure,'fit')}</div><div class="section-label">${T.spaces}</div><div class="object-list">${g.zones.map(z=>objectRow('zone',z,'plan',`${Math.round(z.width)} × ${Math.round(z.depth)} ${T.centimeters}`)).join('')||`<p class="muted">${T.empty}</p>`}</div><div class="section-label">${T.structures}</div><div class="structure-buttons">${button('add-wall',T.addWall)}${button('add-door',T.addDoor)}${button('add-sliding',T.addSliding)}${button('add-window',T.addWindow)}</div><div class="object-list">${g.structures.map(o=>objectRow('structure',o,o.type==='wall'?'plan':'home',`${Math.round(o.width??o.length)} ${T.centimeters}`)).join('')}</div>`;
  if(g.backgroundPlan)content+=`<div class="section-label">${T.background}</div><div class="background-card"><span>${esc(g.backgroundPlan.name)}</span>${button('calibrate',T.calibration,'fit')}${button('recognize',T.recognize,'plan')}<label class="field"><span>${T.opacity}</span><input id="background-opacity" type="range" min="0" max="1" step=".05" value="${g.backgroundPlan.opacity??.45}"></label>${button('background-settings',T.settings??T.properties,'settings','text-button')}${button('remove-background',T.removeBackground,'trash','text-button')}</div>`;
 }else if(leftTab==='furniture'){
  content=`<div class="panel-heading"><div><span class="eyebrow">${T.furniture}</span><h2>${T.furnitureTitle}</h2></div></div><input class="search" id="furniture-search" placeholder="${T.searchFurniture}" aria-label="${T.searchFurniture}"><div class="catalog" id="catalog-list">${catalog.map(c=>`<button class="catalog-card" data-action="add-furniture" data-key="${c.key}" data-search="${c.name}"><div class="catalog-illustration ${c.type}">${furnitureIllustration(c)}</div><strong>${c.name}</strong><small>${c.width} × ${c.depth} × ${c.height}</small><span class="catalog-add">+</span></button>`).join('')}</div><div class="section-label">${T.selected} / ${T.furniture}</div><div class="object-list">${g.items.map(i=>objectRow('item',i,'sofa',`${i.width} × ${i.depth} ${T.centimeters}`)).join('')}</div>`;
 }else{
  content=`<div class="panel-heading"><div><span class="eyebrow">${T.templates}</span><h2>${T.templatesTitle}</h2></div></div><div class="section-label">${T.roomTemplates}</div>${examples.map(e=>`<button data-action="example-project" data-key="${e.id}" class="template-card">${icon(e.icon,40)}<div><strong>${e.name}</strong><small>${e.description}</small></div>${icon('chevron',16)}</button>`).join('')}<div class="section-label">${T.groupTemplates}</div>${builtins.map(t=>templateCard(t,false)).join('')}<div class="section-label">${T.needTemplates}</div>${needPresets.map(t=>button('need-preset',t.name,'plus','preset',`data-key="${t.id}"`)).join('')}<div class="section-label">${T.personalTemplates}</div>${personalTemplates.map(t=>templateCard(t,true)).join('')||`<p class="muted">${T.noTemplates}</p>`}${button('import-template',T.templateImport,'export','wide')}`;
 }
 $('#left-content').innerHTML=content;
}
function objectRow(kind,o,ico,subtitle){const selected=selection.some(s=>s.id===o.id);return `<div class="object-row ${selected?'selected':''}"><input type="checkbox" data-select-kind="${kind}" data-select-id="${esc(o.id)}" aria-label="${T.select} ${esc(o.name)}" ${selected?'checked':''}><button data-action="select-object" data-kind="${kind}" data-id="${esc(o.id)}">${icon(ico,18)}<span><strong>${esc(o.name)}</strong><small>${subtitle}</small></span>${o.locked?icon('lock',13):''}${o.confirmed?'':'<i class="pending-dot" title="'+T.pending+'"></i>'}</button>${tiny('delete-object',`${T.delete} ${o.name}`,'trash',`data-kind="${kind}" data-id="${esc(o.id)}" ${scheme().protected||o.locked?'disabled':''}`)}</div>`;}
function furnitureIllustration(c){if(c.type==='bed')return '<div class="mini-bed"><i></i><i></i><b></b></div>';if(c.type==='sofa')return '<div class="mini-sofa"><i></i><i></i><i></i></div>';if(['desk','table'].includes(c.type))return '<div class="mini-table"><i></i><b></b></div>';if(c.type==='wardrobe')return '<div class="mini-cabinet"><i></i><b></b></div>';if(c.type==='plant')return icon('leaf',40);return icon(c.type==='chair'?'sofa':'cube',40);}
function templateCard(t,personal){return `<div class="template-card"><button class="template-main" data-action="insert-template" data-id="${esc(t.id)}" data-personal="${personal}">${icon('group',30)}<span><strong>${esc(t.name)}</strong><small>${t.items.length} ${T.furniture}</small></span>${icon('plus',16)}</button>${personal?tiny('delete-template',T.delete,'trash',`data-id="${esc(t.id)}"`):''}</div>`;}
function renderRight(){const s=scheme(),stale=!s.check||s.check.stale||s.check.revision!==project.revision;$('#right-tabs').innerHTML=[['properties','settings'],['needs','home'],['checks','check']].map(([k,i])=>button(`right-${k}`,T[k],i,rightTab===k?'active':'')).join('');
 $('#right-content').innerHTML=rightTab==='properties'?propertiesMarkup():rightTab==='needs'?needsMarkup():checksMarkup(stale);}
function propertiesMarkup(){const selected=selectedObjects(),group=selectedGroup();let html='';
 if(!selected.length){const s=scheme();return `<div class="panel-heading"><div><span class="eyebrow">${T.summary}</span><h2>${T.summaryTitle}</h2></div>${icon('leaf',23)}</div><p class="muted">${T.selectionHint}</p><div class="summary-grid"><div><strong>${(geometry().zones.reduce((n,z)=>n+z.width*z.depth,0)/10000).toFixed(1)}</strong><small>m² · ${T.area}</small></div><div><strong>${geometry().items.length}</strong><small>${T.objects}</small></div></div><div class="section-label">${T.style}</div>${stylePicker()}${textArea(T.schemeNotes,'scheme.notes',s.notes)}${textArea(T.pendingNotes,'scheme.pending',s.pending.join('\n'))}<div class="tip">${T.multiHint}</div>${button('edit-needs',T.needs,'home','wide')}${button('run-checks',T.refreshChecks,'check','wide')}<label class="check-label" style="margin-top:18px"><input type="checkbox" id="auto-walls" ${geometry().automaticWalls!==false?'checked':''}>${T.autoWalls}</label>`;}
 if(selected.length>1){const b=polygonBounds(selectedItems().flatMap(i=>footprint(i)));html=`<div class="panel-heading"><div><span class="eyebrow">${selected.length} ${T.selected}</span><h2>${esc(group?.name??T.group)}</h2></div>${icon('group',24)}</div>${group?field(T.groupName,'group.name',group.name)+`<label class="check-label"><input data-field="group.allowInternalOverlap" type="checkbox" ${group.allowInternalOverlap?'checked':''}>${T.internalOverlap}</label>`:''}<div class="inline-actions">${button('rotate',T.rotation+' 15°','rotate')}${button('duplicate',T.duplicate,'copy')}${button('delete-selection',T.delete,'trash')}</div>${selectedItems().length===selected.length?`<div class="field-grid">${numberField(T.x,'multi.x',b.x+b.width/2)}${numberField(T.y,'multi.y',b.y+b.depth/2)}</div>${button('save-template',T.saveTemplate,'template','wide')}${group?button('enter-group',T.enterGroup,'group','wide')+button('ungroup',T.ungroup,'group','wide'):button('group',T.groupSelected,'group','wide')}`:''}${button('lock-selection',selected.every(s=>s.object.locked)?T.unlock:T.lock,'lock','wide')}`;return html;}
 const {object:o,kind}=selected[0];if(kind==='dimension')return `${field(T.name,'object.name',o.name)}<div class="field-grid">${numberField('X1','object.x1',o.x1)}${numberField('Y1','object.y1',o.y1)}${numberField('X2','object.x2',o.x2)}${numberField('Y2','object.y2',o.y2)}</div>${field(T.source,'object.source',o.source)}<div class="inline-actions">${button('duplicate',T.duplicate,'copy')}${button('lock-selection',o.locked?T.unlock:T.lock,'lock')}${button('delete-selection',T.delete,'trash')}</div>`;html=`<div class="panel-heading"><div><span class="eyebrow">${kind==='zone'?T.spaces:kind==='item'?T.furniture:T.structures}</span><h2>${esc(o.name)}</h2></div>${icon(kind==='item'?'sofa':'plan',24)}</div>${isolatedGroup?`<div class="group-context">${esc(scheme().groups.find(g=>g.id===isolatedGroup)?.name)}${button('leave-group',T.leaveGroup)}</div>`:''}${field(T.name,'object.name',o.name)}<div class="inline-actions">${button('duplicate',T.duplicate,'copy')}${button('lock-selection',o.locked?T.unlock:T.lock,'lock')}${button('delete-selection',T.delete,'trash')}</div><div class="section-label">${T.dimensions} · ${T.centimeters}</div><div class="field-grid">`;
 if(kind==='structure'){html+=numberField(o.type==='wall'?T.length:T.width,`object.${o.type==='wall'?'length':'width'}`,o.length??o.width,.1,10000)+numberField(T.height,'object.height',o.height,.1,10000)+(o.type==='wall'?numberField(T.thickness,'object.thickness',o.thickness,1,200):'');}
 else html+=numberField(T.width,'object.width',o.width,.1,10000)+numberField(T.depth,'object.depth',o.depth,.1,10000)+numberField(T.height,'object.height',o.height,.1,10000);
 if(kind==='item')html+=numberField(T.elevation,'object.elevation',o.elevation??0,0,10000);
 html+=`</div><div class="section-label">${T.position}</div><div class="field-grid">${numberField(T.x,'object.x',o.x)}${numberField(T.y,'object.y',o.y)}${kind!=='zone'?numberField(T.rotation,kind==='structure'?'object.angle':'object.rotation',o.rotation??o.angle??(o.orientation==='vertical'?90:0),-36000,36000):''}</div>`;
 if(kind==='zone')html+=button('polygon-edit',polygonEdit?T.leaveGroup:T.editVertices,'plan','wide')+textArea(T.verticesHint,'object.vertices',zonePoints(o).map(p=>`${Math.round(p.x*100)/100}, ${Math.round(p.y*100)/100}`).join('\n'));
 if(kind==='structure'&&o.type!=='wall'){
  if(o.type==='door')html+=selectField(T.doorType,'object.doorType',[['swing',T.swing],['sliding',T.sliding]],o.doorType)+selectField(T.hinge,'object.hinge',[['start',T.start],['end',T.end]],o.hinge??'start')+selectField(T.openSide,'object.openSide',[[-1,T.negative],[1,T.positive]],o.openSide??-1)+numberField(o.doorType==='sliding'?T.doorRatio:T.doorAngle,`object.${o.doorType==='sliding'?'openRatio':'openAngle'}`,o.doorType==='sliding'?o.openRatio:o.openAngle,0,o.doorType==='sliding'?100:120);
  else html+=numberField(T.sillHeight,'object.sillHeight',o.sillHeight,0,10000)+numberField(T.doorRatio,'object.openRatio',o.openRatio,0,100);
  html+=button('attach-opening',T.attach,'plan','wide')+`<label class="check-label" style="margin-top:12px"><input type="checkbox" data-field="object.transparent" ${o.transparent?'checked':''}>${T.transparent}</label>`;
 }
 if(kind==='item'){
  html+=selectField(T.category,'object.category',Object.entries(labels.categories),o.category??'other')+selectField(T.type,'object.type',Object.entries(labels.types),o.type)+selectField(T.material,'object.material',[['style',T.style],['custom',T.customFurniture]],o.material??'style')+field(T.color,'object.color',o.color,'color')+`<label class="check-label"><input type="checkbox" data-field="object.transparent" ${o.transparent?'checked':''}>${T.transparent}</label>`;
  if(o.type==='bed')html+=`<div class="section-label">${T.mattress}</div><div class="field-grid">${numberField(T.mattressWidth,'object.mattress.width',o.mattress?.width??o.width,.1,10000)}${numberField(T.mattressDepth,'object.mattress.depth',o.mattress?.depth??o.depth,.1,10000)}</div>`;
  html+=`<details class="property-details"><summary>${T.collision}</summary><p class="muted">${T.customCollision}</p><div class="field-grid">${numberField(T.collisionWidth,'object.collision.width',o.collision?.width??o.width,.1,10000)}${numberField(T.collisionDepth,'object.collision.depth',o.collision?.depth??o.depth,.1,10000)}</div></details><details class="property-details"><summary>${T.useSpace}</summary><p class="muted">${T.useHint}</p>${selectField(T.usageState,'object.state',[['stored',T.stored],['inUse',T.inUse]],o.state??'stored')}${selectField(T.conditions,'object.useSpace.when',[['inUse',T.onlyInUse],['always',T.always]],o.useSpace?.when??'inUse')}<div class="field-grid">${['front','back','left','right'].map(k=>numberField(T[k],`object.useSpace.${k}`,o.useSpace?.[k]??0,0,1000)).join('')}${numberField(T.stateShift+' X','object.stateOffset.x',o.stateOffset?.x??0,-1000,1000)}${numberField(T.stateShift+' Y','object.stateOffset.y',o.stateOffset?.y??0,-1000,1000)}</div></details>${button('save-template',T.saveTemplate,'template','wide')}`;
 }
 html+=`<div class="section-label">${T.basis}</div>${selectField(T.dimensionStatus,'object.confirmed',[[false,T.pending],[true,T.measured]],o.confirmed===true)}${field(T.source,'object.source',o.source)}${textArea(T.notes,'object.notes',o.notes)}`;return html;}
function stylePicker(){return `<div class="style-picker">${project.styles.map(s=>`<button data-action="style" data-id="${s.id}" class="${s.id===project.activeStyleId?'active':''}"><span class="palette"><i style="background:${esc(s.floor)}"></i><i style="background:${esc(s.fabric)}"></i><i style="background:${esc(s.wood)}"></i></span>${esc(s.name)}${s.id===project.activeStyleId?icon('check',14):''}</button>`).join('')}${button('edit-style',T.editStyle,'settings','text-button')}</div>`;}
function needsMarkup(){const n=project.needs,s=scheme();return `<div class="panel-heading"><div><span class="eyebrow">${T.needs}</span><h2>${T.needsTitle}</h2></div>${icon('home',23)}</div><p class="muted">${T.needIntro}</p><div class="need-summary"><strong>${n.residents}</strong><span>${T.residents}</span><small>${n.members.map(m=>esc(m.name)).join(' · ')}</small></div>${button('edit-needs',T.needs+' · '+T.properties,'settings','primary wide')}<div class="section-label">${T.requirements}</div>${n.entries.map(e=>{const r=requirementStatus(e,s.check&&!s.check.stale?s.check:null);return `<div class="need-card"><span class="priority ${e.priority}">${labels.priorities[e.priority]}</span><p>${esc(e.text)}</p><small class="${r.status}">${labels.statuses[r.status]} · ${esc(r.detail)}</small>${e.kind==='retained'&&e.width?`<small>${e.width} × ${e.depth} × ${e.height} ${T.centimeters}</small>`:''}</div>`;}).join('')||`<p class="muted">${T.empty}</p>`}<div class="section-label">${T.purposes}</div>${n.purposes.map(p=>`<div class="need-card"><small>${esc(geometry().zones.find(z=>z.id===p.roomId)?.name??T.room)}</small><p>${esc(p.text)}</p></div>`).join('')}<div class="section-label">${T.preferredStyle}</div><p class="plain-note">${esc(n.preferredStyle)||'—'}</p><div class="section-label">${T.notes}</div><p class="plain-note">${esc(n.notes)||'—'}</p>`;}
function checksMarkup(stale){const s=scheme();return `<div class="panel-heading"><div><span class="eyebrow">${T.checks}</span><h2>${T.checksTitle}</h2></div>${icon('check',24)}</div><p class="muted">${T.checksIntro}</p><div class="check-state ${stale?'stale':''}">${icon(stale?'rotate':'check',15)}${stale?T.checkStale:T.checkFresh}</div><div class="inline-actions">${button('run-checks',T.refreshChecks,'check','primary')}${button('add-rule',T.addRule,'plus')}</div>${s.rules.map(rule=>{const r=s.check?.results.find(r=>r.id===rule.id);return `<article class="rule-card ${!rule.enabled?'disabled':''}"><div class="rule-title"><label class="check-label"><input type="checkbox" data-rule-toggle="${rule.id}" ${rule.enabled?'checked':''}><strong>${esc(rule.name)}</strong></label>${tiny('edit-rule',T.properties,'settings',`data-id="${rule.id}"`)}</div><button class="rule-result" data-action="locate-rule" data-id="${rule.id}"><span class="status-badge ${stale?'pending':r?.status??'pending'}">${stale?T.unchecked:labels.statuses[r?.status]??T.unchecked}</span><span><b>${stale?'—':esc(r?.value??'—')}</b><small>${T.target} ${stale?'—':esc(r?.target??'—')}</small></span>${icon('chevron',15)}</button>${!stale&&r?`<p class="rule-detail">${esc(r.detail)}</p><details><summary>${T.conditions}</summary><p class="rule-detail">${esc(r.conditions)}</p><p class="rule-detail">${r.objectIds.map(id=>esc([...geometry().items,...geometry().structures].find(o=>o.id===id)?.name??id)).join('、')}</p></details>`:''}</article>`;}).join('')}`;}
function renderCanvas(rebuild=true){const g=geometry();renderSelectionActions();plan.setData(g,selection,{style:currentStyle(),grid,overlay,tool,polygonEdit,drawPoints});if(three){if(rebuild)three.update(g,currentStyle(),selection,project.walk);else three.select(selection);three.setVisible(mode!=='2d');}$('#plan-host').hidden=mode!=='2d';
 $('#viewport-info').innerHTML=`<div><span class="eyebrow">${three?.walking?T.walkSettings:mode==='2d'?T.plan2d:T.scene3d}</span><h1>${esc(scheme().name)}</h1><span class="canvas-subtitle">${scheme().protected?T.protected:tool==='draw'?T.drawingHint:tool.startsWith('pick-')?T.select:tool==='calibrate'?T.calibrationHint:T.dimensionsLabel}</span></div>${scheme().protected?'<span class="protected-badge">'+icon('lock',13)+T.protected+'</span>':''}`;
 $('#canvas-tools').innerHTML=three?.walking?'':`${tiny('tool-select',T.select,'cursor',tool==='select'?'aria-pressed="true"':'')}${tiny('tool-pan',T.pan,'hand',tool==='pan'?'aria-pressed="true"':'')}<span></span>${tiny('zoom-in',T.zoomIn,'plus')}${tiny('zoom-out',T.zoomOut,'cross')}${tiny('fit',T.fit,'fit')}`;
 $('#canvas-bottom').innerHTML=three?.walking?walkMarkup():`<div class="canvas-bottom-left"><label><input type="checkbox" id="grid-toggle" ${grid?'checked':''}>${T.grid}</label><label><input type="checkbox" id="snap-toggle" ${snapping?'checked':''}>${T.snap}</label>${tool==='draw'?button('finish-draw',T.finishDraw,'check','primary small'):''}${isolatedGroup?button('leave-group',T.leaveGroup):''}</div><div class="canvas-bottom-right">${mode==='3d'?`<label><input id="cutaway-toggle" type="checkbox" ${three?.cutaway?'checked':''}>${T.cutaway}</label>`:''}<span class="style-dot" style="background:${currentStyle().fabric}"></span><button data-action="style-menu">${esc(currentStyle().name)}</button><span>1 : ${Math.max(1,Math.round(plan.view.width/100))}</span></div>`;
 $('#walk-controls').hidden=!three?.walking;$('#statusbar').innerHTML=`<span><i></i>${T.statusLocal}</span><span>${selection.length?selection.length+' '+T.selected:T.multiHint}</span><span>${T.brand} · Room Studio</span>`;
 document.body.dataset.mode=three?.walking?'walk':mode;document.body.dataset.mobilePanel=mobilePanel??'';
}
function renderSelectionActions(){
 const objects=selectedObjects(),host=$('#selection-actions');
 host.hidden=!objects.length||!!three?.walking||tool!=='select';
 if(host.hidden){host.innerHTML='';return;}
 const locked=objects.some(s=>s.object.locked),protectedScheme=scheme().protected;
 host.innerHTML=`<strong>${objects.length===1?esc(objects[0].object.name):`${objects.length} ${T.selected}`}</strong>${protectedScheme?button('schemes',T.protected,'lock'):locked?button('unlock-selection',T.unlock,'lock'):''}${button('duplicate',T.duplicate,'copy','',protectedScheme?'disabled':'')}${button('delete-selection',T.delete,'trash','delete-button',protectedScheme||locked?'disabled':'')}`;
}
function walkMarkup(){return `<div class="walk-panel"><div class="walk-controls-title">${icon('walk',20)}<strong>${T.walkSettings}</strong>${button('walk',T.exitWalk,'cross','small')}</div><div class="walk-fields">${numberField(T.eyeHeight,'walk.eyeHeight',project.walk.eyeHeight,80,220)}${numberField(T.speed,'walk.speed',project.walk.speed,.2,4)}${numberField(T.horizontalFov,'walk.hfov',project.walk.hfov,40,110)}${numberField(T.bodyRadius,'walk.radius',project.walk.radius,10,50)}<label class="field"><span>${T.jumpRoom}</span><select id="jump-room"><option value="">${T.select}</option>${geometry().zones.map(z=>option(z.id,z.name,'')).join('')}</select></label>${button('walk-reset',T.reset,'fit','small')}</div><p>${T.eyeHint}</p><small>${T.walkHint}</small></div>`;}
function renderAll(rebuild=true){renderHeader();renderLeft();renderRight();renderCanvas(rebuild);}
function select(kind,id,add=false){if(add){const i=selection.findIndex(s=>s.id===id);if(i>=0)selection.splice(i,1);else selection.push({kind,id});}else if(!selection.some(s=>s.id===id)||selection.length===1){selection=[{kind,id}];}
 if(kind==='item'&&!isolatedGroup){const group=scheme().groups.find(g=>g.itemIds.includes(id));if(group){for(const gid of group.itemIds)if(!selection.some(s=>s.id===gid))selection.push({kind:'item',id:gid});}}
 polygonEdit=false;rightTab='properties';renderAll(false);
}
function pointerEdit(phase,delta){
 if(phase==='begin'){if(!editable()||selectedObjects().some(s=>s.object.locked)){editBase=null;if(selectedObjects().some(s=>s.object.locked))toast(T.protectedObject);return;}editBase=clone(project);return;}
 if(!editBase)return;
 if(phase==='cancel'){project=editBase;editBase=null;renderAll();return;}
 if(phase==='preview'){
  project=clone(editBase);const s=scheme(),g=geometry(),selected=selectedObjects();
  if(delta.vertex){const r=g.zones.find(z=>z.id===delta.vertex.id),points=zonePoints(r);points[delta.vertex.index]={x:snapValue(delta.vertex.point.x),y:snapValue(delta.vertex.point.y)};try{Object.assign(r,zoneFromPoints(r,points));}catch{return;}}
  else if(delta.resize){const item=selectedItems()[0];if(!item)return;const dx=delta.resize.x-item.x,dy=delta.resize.y-item.y,r=-(item.rotation??0)*Math.PI/180;item.width=Math.max(1,snapValue(Math.abs(dx*Math.cos(r)-dy*Math.sin(r))*2));item.depth=Math.max(1,snapValue(Math.abs(dx*Math.sin(r)+dy*Math.cos(r))*2));}
  else if(delta.angle!==undefined){const items=selectedItems(),b=polygonBounds(items.flatMap(i=>footprint(i))),center=delta.center??{x:b.x+b.width/2,y:b.y+b.depth/2};const moved=transformItems(items,{angle:delta.angle,cx:center.x,cy:center.y});for(const i of moved)Object.assign(g.items.find(o=>o.id===i.id),i);}
  else for(const {kind,object:o}of selected){if(kind==='dimension'){o.x1+=snapValue(delta.dx);o.x2+=snapValue(delta.dx);o.y1+=snapValue(delta.dy);o.y2+=snapValue(delta.dy);continue;}o.x+=snapValue(delta.dx);o.y+=snapValue(delta.dy);if(kind==='structure'&&o.wallAttachment)delete o.wallAttachment;}
  if(selected.some(o=>o.kind==='zone')){const repaired=reconcileZoneOpenings(activeScheme(editBase).geometry,g);if(!repaired){project=clone(editBase);return;}s.geometry=repaired;}
  if(mode==='2d')renderCanvas(false);else renderCanvas(true);return;
 }
 if(phase==='commit'){const before=editBase;editBase=null;if(history.commit(before,project)){markChanged();renderAll();}}
}
const snapValue=v=>snapping?Math.round(v/5)*5:Math.round(v*10)/10;
function centerPoint(){const v=plan.view;return{x:snapValue(v.x+v.width/2),y:snapValue(v.y+v.height/2)};}
function onCanvasPoint(point){const p={x:snapValue(point.x),y:snapValue(point.y)};if(tool==='draw'){if(drawPoints.length>=3&&Math.hypot(p.x-drawPoints[0].x,p.y-drawPoints[0].y)<15){finishDrawing();return;}drawPoints.push(p);renderCanvas(false);}
 else if(tool==='measure'){drawPoints.push(point);if(drawPoints.length===2){const [a,b]=drawPoints,d={id:uid('dim'),name:T.measurement,x1:a.x,y1:a.y,x2:b.x,y2:b.y,source:'',locked:false};mutate((_,s,g)=>g.dimensions.push(d));selection=[{kind:'dimension',id:d.id}];drawPoints=[];tool='select';renderAll();}else renderCanvas(false);}
 else if(tool==='calibrate'){drawPoints.push(point);if(drawPoints.length===2){const [a,b]=drawPoints;tool='select';drawPoints=[];textDialog(T.calibration,T.actualLength,100,value=>{const length=Number(value);if(mutate((_,s,g)=>{g.backgroundPlan=calibratePlan(g.backgroundPlan,a,b,length);})){plan.fit();toast(T.calibrationDone);if(recognizeAfterCalibration){recognizeAfterCalibration=false;recognizePlan();}}});}renderCanvas(false);}
 else if(tool.startsWith('pick-')){const [_,id,key]=tool.split('|');mutate((_,s)=>{s.rules.find(r=>r.id===id)[key]=p;});tool='select';openRule(id);renderCanvas(false);}
}
function finishDrawing(){if(drawPoints.length<3){toast(T.invalidPolygon);return;}try{const room=zoneFromPoints(roomFrom(`${T.spaces} ${geometry().zones.length+1}`),drawPoints);mutate((_,s,g)=>g.zones.push(room));drawPoints=[];tool='select';selection=[{kind:'zone',id:room.id}];renderAll();}catch{toast(T.invalidPolygon);}}
let dialogAction=null;
function showDialog(title,content,{onChange=null,onClick=null,wide=false}={}){const dialog=$('#dialog');dialogCleanup?.();dialogCleanup=null;dialogAction=null;dialog.classList.toggle('wide-dialog',wide);$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=content;$('#dialog-body').onchange=onChange?e=>{e.stopPropagation();guarded(onChange)(e);}:null;$('#dialog-body').onclick=onClick?e=>onClick(e):null;if(!dialog.open)dialog.showModal();}
function closeDialog(){$('#dialog').close();dialogAction=null;dialogCleanup?.();dialogCleanup=null;}
function textDialog(title,label,value,onApply){showDialog(title,`${field(label,'dialog.value',value)}<div class="dialog-actions">${button('close-dialog',T.cancel)}${button('dialog-apply',T.apply,'check','primary')}</div>`);dialogAction=()=>{const v=$('#dialog-body [data-field]').value;closeDialog();return onApply(v);};$('#dialog-body input')?.focus();$('#dialog-body input')?.select();}
function confirmDialog(title,copy,onApply){showDialog(title,`<p class="muted">${copy}</p><div class="dialog-actions">${button('close-dialog',T.cancel)}${button('dialog-apply',T.confirm,'check','primary')}</div>`);dialogAction=()=>{closeDialog();return onApply();};}
function openProjects(){showDialog(T.projects,`<div class="project-list">${[...projectCache.values()].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(p=>`<div class="project-card"><button data-action="open-project" data-id="${p.id}">${icon('plan',30)}<span><strong>${esc(p.name)}</strong><small>${p.schemes.length} ${T.layout} · ${esc(new Date(p.updatedAt).toLocaleString('zh-CN'))}</small></span>${p.id===project.id?icon('check',18):icon('chevron',18)}</button>${tiny('rename-project',T.rename,'settings',`data-id="${p.id}"`)}${tiny('delete-project',T.delete,'trash',`data-id="${p.id}"`)}</div>`).join('')}</div><div class="dialog-actions">${button('import-file',T.restore,'export')}${button('backup-all',T.backupAll,'export')}${button('new-project',T.newProject,'plus','primary')}</div>`,{wide:true});}
function newProjectDialog(){showDialog(T.newProject,`<h2 class="dialog-intro">${T.welcomeTitle}</h2><p class="muted">${T.welcomeCopy}</p><div class="example-grid"><button data-action="create-blank" class="example-card">${icon('plus',40)}<strong>${T.blank}</strong><small>${T.create} · ${T.emptyProject}</small></button>${examples.map(e=>`<button data-action="example-project" data-key="${e.id}" class="example-card">${icon(e.icon,40)}<strong>${e.name}</strong><small>${e.description}</small></button>`).join('')}</div>`,{wide:true});}
async function useProject(p,{fresh=false}={}){await saveNow();if(three?.walking)three.exit();project=clone(p);if(fresh){project.id=uid('project');project.updatedAt=new Date().toISOString();}projectCache.set(project.id,clone(project));selection=[];overlay=null;isolatedGroup=null;history.clear();tool='select';mode='2d';saveStatus='unsaved';await saveNow();await store?.put('meta',{id:'last-project',projectId:project.id}).catch(()=>{});renderAll();plan.fit();closeDialog();}
function schemeDialog(){const s=scheme();showDialog(T.layout,`${field(T.schemeName,'scheme.name',s.name)}${textArea(T.schemeNotes,'scheme.notes',s.notes)}${textArea(T.pendingNotes,'scheme.pending',s.pending.join('\n'))}<div class="dialog-actions">${button('protect-scheme',s.protected?T.unprotect:T.protect,'lock')}${button('delete-scheme',T.deleteScheme,'trash')}${button('duplicate-scheme',T.addScheme,'copy','primary')}</div>`);}
function needsDialog(){const n=project.needs;showDialog(T.needs,`<p class="muted">${T.needIntro}</p>${numberField(T.residents,'needs.residents',n.residents,1,100)}<div class="dialog-section"><h3>${T.members}</h3>${button('add-member',T.add,'plus','small')}</div>${n.members.map(m=>`<div class="repeat-row" data-member="${m.id}">${field(T.member,`members.${m.id}.name`,m.name)}${field(T.traits,`members.${m.id}.traits`,m.traits)}${tiny('remove-member',T.deleteEntry,'trash',`data-id="${m.id}"`)}</div>`).join('')}<div class="dialog-section"><h3>${T.purposes}</h3>${button('add-purpose',T.add,'plus','small')}</div><p class="muted">${T.purposeHelp}</p>${n.purposes.map(p=>`<div class="repeat-row">${selectField(T.room,`purposes.${p.id}.roomId`,[['',T.room],...geometry().zones.map(z=>[z.id,z.name])],p.roomId)}${field(T.purpose,`purposes.${p.id}.text`,p.text)}${tiny('remove-purpose',T.deleteEntry,'trash',`data-id="${p.id}"`)}</div>`).join('')}<div class="dialog-section"><h3>${T.requirements}</h3>${button('add-need',T.add,'plus','small')}</div>${n.entries.map(e=>`<div class="requirement-edit"><div class="repeat-row">${field(T.requirement,`entries.${e.id}.text`,e.text)}${tiny('remove-need',T.deleteEntry,'trash',`data-id="${e.id}"`)}</div><div class="field-grid">${selectField(T.priority,`entries.${e.id}.priority`,Object.entries(labels.priorities),e.priority)}${selectField(T.needKind,`entries.${e.id}.kind`,Object.entries(labels.kinds),e.kind)}</div>${selectField(T.constraint,`entries.${e.id}.constraint`,[['',T.noConstraint],['fixed',T.fixed],['flexible',T.flexible],['pending',T.pending]],e.constraint??'')}${selectField(T.linkedRule,`entries.${e.id}.ruleId`,[['',T.noRule],...scheme().rules.map(r=>[r.id,r.name])],e.ruleId??'')}${e.kind==='retained'?`<div class="field-grid">${numberField(T.width,`entries.${e.id}.width`,e.width??100,.1,10000)}${numberField(T.depth,`entries.${e.id}.depth`,e.depth??50,.1,10000)}${numberField(T.height,`entries.${e.id}.height`,e.height??80,.1,10000)}</div>${selectField(T.targetObject,`entries.${e.id}.objectId`,[['',T.select],...geometry().items.map(i=>[i.id,i.name])],e.objectId??'')}`:''}</div>`).join('')}${field(T.preferredStyle,'needs.preferredStyle',n.preferredStyle)}${textArea(T.notes,'needs.notes',n.notes)}<div class="dialog-actions">${button('close-dialog',T.close,'check','primary')}</div>`,{wide:true,onChange:e=>{const el=e.target,key=el.dataset.field;if(!key)return;const value=readValue(el);mutate((p)=>{const parts=key.split('.');if(parts[0]==='needs')p.needs[parts[1]]=value;else{const row=p.needs[parts[0]].find(x=>x.id===parts[1]);row[parts[2]]=value;}},{needs:true,protect:false});if(key.endsWith('.kind'))needsDialog();}});}
function openRule(id=null){let r=scheme().rules.find(x=>x.id===id);if(!r){r=newRule();if(!mutate((_,s)=>s.rules.push(r)))return;}const objects=[...geometry().items,...geometry().structures],opts=[['',T.select],...objects.map(i=>[i.id,i.name])];
 let content=`${field(T.name,'rule.name',r.name)}${selectField(T.checkType,'rule.type',Object.entries(labels.rules),r.type)}${selectField(T.relatedRoom,'rule.roomId',[['',T.allObjects],...geometry().zones.map(z=>[z.id,z.name])],r.roomId??'')}`;
 if(r.type==='clearance')content+=selectField(T.objectA,'rule.objectA',opts,r.objectA??'')+selectField(T.objectB,'rule.objectB',opts,r.objectB??'')+numberField(T.clearanceTarget,'rule.threshold',r.threshold??80,0,10000);
 if(r.type==='path'){content+=numberField(T.pathTarget,'rule.threshold',r.threshold??80,1,300)+numberField(T.pathStep,'rule.gridStep',r.gridStep??10,1,20);for(const key of ['start','end'])content+=`<div class="section-label">${key==='start'?T.startPoint:T.endPoint}</div><div class="field-grid">${numberField(T.pointX,`rule.${key}.x`,r[key]?.x??0)}${numberField(T.pointY,`rule.${key}.y`,r[key]?.y??0)}</div>${button('pick-rule-point',key==='start'?T.pickStart:T.pickEnd,'cursor','wide',`data-id="${r.id}" data-key="${key}"`)}<p></p>`;content+=`<label class="check-label"><input data-field="rule.includeUsage" type="checkbox" ${r.includeUsage?'checked':''}>${T.useSpace}</label><p class="muted">${T.routeApprox}</p>`;}
 if(r.type==='visibility')content+=`${selectField(T.targetMode,'rule.targetMode',[['object',T.objectRegion],['area',T.targetArea]],r.targetMode??'object')}${r.targetMode==='area'?`<div class="field-grid">${numberField(T.pointX,'rule.targetArea.x',r.targetArea?.x??100)}${numberField(T.pointY,'rule.targetArea.y',r.targetArea?.y??100)}${numberField(T.areaWidth,'rule.targetArea.width',r.targetArea?.width??100,1,10000)}${numberField(T.areaDepth,'rule.targetArea.depth',r.targetArea?.depth??100,1,10000)}${numberField(T.rotation,'rule.targetArea.rotation',r.targetArea?.rotation??0,-360,360)}</div>`:''}<div class="field-grid">${numberField(T.pointX,'rule.eye.x',r.eye?.x??0)}${numberField(T.pointY,'rule.eye.y',r.eye?.y??0)}</div>${button('pick-rule-point',T.pickEye,'eye','wide',`data-id="${r.id}" data-key="eye"`)}${numberField(T.eyeHeight,'rule.eyeHeight',r.eyeHeight??165,1,400)}${selectField(T.targetObject,'rule.targetId',opts,r.targetId??'')}${numberField(T.targetHeight,'rule.targetHeight',r.targetHeight??65,0,500)}${numberField(T.visibilityTarget,'rule.threshold',r.threshold??0,0,100)}<p class="muted">${T.visibilityApprox}</p>`;
 content+=`<div class="dialog-actions">${button('delete-rule',T.deleteRule,'trash','',`data-id="${r.id}"`)}${button('close-dialog',T.close,'check','primary')}</div>`;
 showDialog(T.rule,content,{onChange:e=>{const el=e.target;if(!el.dataset.field)return;const value=readValue(el),key=el.dataset.field.replace(/^rule\./,'');mutate((_,s)=>setPath(s.rules.find(x=>x.id===r.id),key,value));if(['type','targetMode'].includes(key))openRule(r.id);}});
}
function compareDialog(){const current=scheme(),other=project.schemes.find(s=>s.id!==current.id);if(!other){toast(T.atLeastOne);return;}const v=plan.actualView();showDialog(T.compare,`<p class="muted">${T.comparisonHint}</p><div class="comparison-grid">${[current,other].map(s=>`<div><h3>${esc(s.name)}</h3><svg class="comparison-plan" viewBox="${v.x} ${v.y} ${v.width} ${v.height}" data-scheme="${s.id}"></svg><p class="plain-note">${esc(s.notes)}</p></div>`).join('')}</div><div class="dialog-actions"><label class="field"><span>${T.compareWith}</span><select id="compare-select">${project.schemes.filter(s=>s.id!==current.id).map(s=>option(s.id,s.name,other.id)).join('')}</select></label>${button('close-dialog',T.close)}</div>`,{wide:true});drawCompare(other.id);$('#compare-select').onchange=e=>drawCompare(e.target.value);}
async function drawCompare(otherId){const {planMarkup}=await import('./plan2d.js'),current=scheme();const nodes=[...document.querySelectorAll('.comparison-plan')];[current,project.schemes.find(s=>s.id===otherId)].forEach((s,i)=>{if(nodes[i]&&s){nodes[i].innerHTML=planMarkup(s.geometry,[],{style:currentStyle(),grid:false,interactive:false});nodes[i].previousElementSibling.textContent=s.name;nodes[i].nextElementSibling.textContent=s.notes??'';}});}
function styleDialog(){const s=currentStyle();showDialog(T.editStyle,`${field(T.styleName,'style.name',s.name)}<div class="field-grid">${field(T.floorColor,'style.floor',s.floor,'color')}${field(T.wallColor,'style.wall',s.wall,'color')}${field(T.woodColor,'style.wood',s.wood,'color')}${field(T.fabricColor,'style.fabric',s.fabric,'color')}</div><div class="dialog-actions">${button('copy-style',T.duplicate,'copy')}${button('close-dialog',T.close,'check','primary')}</div>`);}
function exportDialog(){showDialog(T.export,`<div class="export-list">${button('export-project',T.projectFile,'folder','export-row')}${button('backup-all',T.backupAll,'copy','export-row')}${button('export-templates',T.templatesFile,'template','export-row')}${button('export-image',T.image,'image','export-row')}${button('export-report',T.report,'plan','export-row')}</div><p class="muted">${T.statusLocal}</p>`);}
async function importFile(){const file=await chooseFile('.json,.roomstudio');if(!file)return;if(file.size>80*1024*1024)throw Error(T.fileTooLarge);const imported=importProject(await file.text());if(imported.format==='qijian-backup'){if(!store)throw Error(T.storageUnavailable);const restored=await store.restoreBackup(imported);for(const p of restored.projects)projectCache.set(p.id,p);personalTemplates.push(...restored.templates);if(restored.projects.length)await useProject(restored.projects[0]);toast(T.restoreSuccess);}else{imported.id=uid('project');await useProject(imported);toast(T.importSuccess);}}
async function setMode(next){if(next==='2d'){if(three?.walking)three.exit();mode='2d';renderAll(false);return;}
 if(!geometry().zones.length&&!geometry().items.length&&!geometry().structures.length&&geometry().backgroundPlan){await recognizePlan();return;}
 if(!three){try{threeModule??=await import('./scene3d.js');three=new threeModule.Scene3D($('#three-host'),{onSelect:select,onEdit:pointerEdit,onNotice:toast,onDoor:toggleDoor,onWalkChange:()=>renderAll(false)});three.update(geometry(),currentStyle(),selection,project.walk);mode='3d';renderAll(false);three.fit();}catch(e){toast(e.message??T.webglError);return;}}
 else{mode='3d';renderAll(false);}}
function toggleDoor(id){mutate((_,s,g)=>{const door=g.structures.find(d=>d.id===id);if(!door||door.type!=='door')return;if(door.locked)throw Error(T.protectedObject);const key=door.doorType==='sliding'?'openRatio':'openAngle',old=door[key];door[key]=(door[key]??0)>5?0:door.doorType==='sliding'?100:90;
 if(three?.walking&&!canStand(compiledGeometry(g),three.player,project.walk.radius,project.walk.eyeHeight)){door[key]=old;throw Error(T.walkBlocked);}});}
function readValue(el){if(el.type==='checkbox')return el.checked;if(el.type==='number'||el.type==='range'){if(!el.checkValidity()||!Number.isFinite(Number(el.value))||el.value==='')throw Error(T.invalidNumber);return Number(el.value);}return el.value;}
function setPath(object,key,value){const keys=key.split('.');let current=object;for(const k of keys.slice(0,-1)){if(!current[k])current[k]={};current=current[k];}current[keys.at(-1)]=value;}
function changeField(el){const key=el.dataset.field;if(!key)return;let value=readValue(el);
 if(key.startsWith('object.')){
  if(!selectedObjects().length)return;let path=key.slice(7);if(path==='confirmed')value=value==='true';if(path==='openSide')value=Number(value);
  mutate((_,s,g)=>{const {object:o,kind}=selectedObjects()[0];if(o.locked)throw Error(T.protectedObject);
   if(path==='vertices'){const points=value.split('\n').filter(l=>l.trim()).map(l=>{const [x,y]=l.split(/[,，\s]+/).map(Number);if(!Number.isFinite(x)||!Number.isFinite(y))throw Error(T.invalidPolygon);return{x,y};});Object.assign(o,zoneFromPoints(o,points));}
   else if(kind==='zone'&&['x','y','width','depth'].includes(path)){const repaired=updateRoomGeometry(g,o.id,{[path]:value});if(!repaired)throw Error(T.invalidPolygon);s.geometry=repaired;}
   else{setPath(o,path,value);if(kind==='structure'&&['x','y','angle','width'].includes(path)){delete o.wallAttachment;if(path==='angle')o.orientation=value%180===90?'vertical':'horizontal';}}
  });
 }else if(key.startsWith('scheme.'))mutate((_,s)=>{const k=key.slice(7);s[k]=k==='pending'?value.split('\n').filter(Boolean):value;},{protect:key!=='scheme.name'});
 else if(key.startsWith('group.'))mutate(()=>{const g=selectedGroup();g[key.slice(6)]=value;});
 else if(key.startsWith('multi.')){const axis=key.slice(6),items=selectedItems(),b=polygonBounds(items.flatMap(i=>footprint(i))),delta=value-(b[axis]+b[axis==='x'?'width':'depth']/2);mutate(()=>items.forEach(i=>i[axis]+=delta));}
 else if(key.startsWith('style.'))mutate(p=>setPath(p.styles.find(s=>s.id===p.activeStyleId),key.slice(6),value),{protect:false});
 else if(key.startsWith('walk.'))mutate(p=>setPath(p,key,value),{protect:false});
}
