async function importPlan(){
 if(!editable())return;const projectId=project.id,schemeId=scheme().id;
 const file=await chooseFile('image/png,image/jpeg,image/webp');if(!file)return;
 const image=await readPlanImage(file);
 if(project.id!==projectId||scheme().id!==schemeId)return;
 const apply=async newScheme=>{
  if(project.id!==projectId||scheme().id!==schemeId)return;
  if(!mutate((p,s,g)=>{
   if(newScheme){const next=createProject(image.name).schemes[0];next.name=image.name.replace(/\.[^.]+$/,'')+' · 导入';next.geometry.backgroundPlan=image;p.schemes.push(next);p.activeSchemeId=next.id;}
   else g.backgroundPlan=image;
  }))return;
  closeDialog();selection=[];tool='select';drawPoints=[];mobilePanel=null;await setMode('2d');plan.fit();await recognizePlan();
 };
 const g=geometry();
 if(g.zones.length||g.items.length||g.structures.length||g.backgroundPlan){
  showDialog(T.importPlan,`<p>${T.importDestinationHint}</p><div class="dialog-actions">${button('close-dialog',T.cancel)}${button('import-current-plan',T.useCurrentPlan)}${button('dialog-apply',T.newImportScheme,'plan','primary')}</div>`,{onClick:guarded(e=>{if(e.target.closest('[data-action="import-current-plan"]'))return apply(false);})});
  dialogAction=()=>apply(true);
 }else await apply(false);
}
let recognizing=false,recognizeAfterCalibration=false;
async function recognizePlan(){
 if(recognizing||!editable())return;if(!geometry().backgroundPlan)return;if(!geometry().backgroundPlan.id&&!mutate((_,s,g)=>g.backgroundPlan.id=uid('plan')))return;const bg=geometry().backgroundPlan;
 const projectId=project.id,schemeId=scheme().id,controller=new AbortController();recognizing=true;
 showDialog(T.recognize,`<p role="status">${T.recognizeBusy}</p><div class="dialog-actions">${button('close-dialog',T.cancel)}</div>`);
 dialogCleanup=()=>controller.abort();
 try{
  const candidates=await recognizeCandidates(bg,{signal:controller.signal});
  if(controller.signal.aborted||project.id!==projectId||scheme().id!==schemeId||geometry().backgroundPlan!==bg)return;
  // The next dialog replaces the progress dialog, so release its cancellation handler.
  dialogCleanup=null;
  if(!candidates.length){showDialog(T.recognize,`<p>${T.noCandidates}</p><p class="muted">${T.traceHint}</p><div class="dialog-actions">${button('close-dialog',T.keepBackground)}${button('trace-plan',T.drawRoom,'plan','primary')}</div>`);return;}
  const preview=candidates.map((r,i)=>`<polygon points="${zonePoints(r).map(p=>`${p.x},${p.y}`).join(' ')}" fill="#557660" fill-opacity=".18" stroke="#356849" stroke-width="2"/><text x="${r.x+r.width/2}" y="${r.y+r.depth/2}" text-anchor="middle" font-size="16" fill="#244d32">${i+1}</text>`).join('');
  const prior=geometry().zones.some(r=>r.sourcePlanId===bg.id);
  showDialog(T.recognize,`<p class="muted">${T.modelImportHint}</p><svg class="recognition-preview" viewBox="${bg.x} ${bg.y} ${bg.width} ${bg.depth}" aria-label="户型识别轮廓预览"><image href="${esc(bg.dataUrl)}" x="${bg.x}" y="${bg.y}" width="${bg.width}" height="${bg.depth}"/>${preview}</svg>${numberField(T.planWidth,'import.width',bg.width,1,100000)}${candidates.map((r,i)=>`<div class="candidate-row"><input type="checkbox" data-candidate="${i}" checked aria-label="${T.select} ${i+1}"><input data-candidate-name="${i}" value="${esc(r.name)}" aria-label="空间 ${i+1} 名称"><small>${Math.round(r.width)} × ${Math.round(r.depth)} ${T.centimeters}</small></div>`).join('')}${prior?`<p class="muted">${T.replaceCandidatesHint}</p>`:''}<div class="dialog-actions">${button('close-dialog',T.keepBackground)}${button('calibrate-plan',T.calibration,'fit')}${button('dialog-apply',T.confirmCandidates,'check','primary')}</div>`,{wide:true});
  dialogAction=()=>{
   if(project.id!==projectId||scheme().id!==schemeId||geometry().backgroundPlan!==bg){closeDialog();return;}
   const width=readValue($('[data-field="import.width"]'));
   const chosen=candidates.filter((r,i)=>$(`[data-candidate="${i}"]`).checked).map(r=>({...r,name:$(`[data-candidate-name="${candidates.indexOf(r)}"]`).value.trim()||r.name}));
   if(!chosen.length){toast(T.chooseCandidates);return;}
   const rooms=resizeCandidates(chosen,bg,width),ratio=width/bg.width;
   const success=mutate((_,s,g)=>{
    const previous=new Set(g.zones.filter(r=>r.sourcePlanId===bg.id).map(r=>r.id));
    g.zones=g.zones.filter(r=>!previous.has(r.id));
    g.structures=g.structures.filter(o=>!previous.has(o.wallAttachment?.zoneId));
    g.backgroundPlan={...bg,width,depth:bg.depth*ratio,confirmed:ratio===1&&bg.confirmed,calibration:ratio===1?bg.calibration:undefined};
    g.zones.push(...rooms);g.automaticWalls=true;
   });
   if(!success)return;closeDialog();selection=[];tool='select';polygonEdit=false;mobilePanel=null;renderAll();plan.fit();three?.fit();toast(T.modelReady);
  };
 }catch(e){if(e.name!=='AbortError'){showDialog(T.recognize,`<p>${T.recognizeFailed}</p><div class="dialog-actions">${button('close-dialog',T.close)}${button('trace-plan',T.drawRoom,'plan','primary')}</div>`);console.error(e);}}
 finally{recognizing=false;}
}
function addStructure(type){const c=centerPoint(),o={id:uid(type),name:({wall:T.addWall,door:T.addDoor,sliding:T.addSliding,window:T.addWindow})[type],x:c.x,y:c.y,type:type==='sliding'?'door':type,angle:0,orientation:'horizontal',height:type==='wall'?270:type==='window'?130:210,confirmed:false,source:'',locked:false};if(type==='wall')Object.assign(o,{length:200,thickness:10});else if(type==='window')Object.assign(o,{width:150,sillHeight:90,openRatio:0});else Object.assign(o,{width:type==='sliding'?150:90,doorType:type==='sliding'?'sliding':'swing',hinge:'start',openSide:-1,openAngle:90,openRatio:0});if(mutate((_,s,g)=>g.structures.push(o))){selection=[{kind:'structure',id:o.id}];renderAll();}}
