document.addEventListener('click',guarded(async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;await actions[el.dataset.action]?.(el,e);}));
document.addEventListener('change',guarded(async e=>{const el=e.target;if(el.closest('#dialog-body')?.onchange)return;
 if(el.dataset.field){changeField(el);return;}
 if(el.id==='scheme-select'){if(three?.walking)three.exit();project.activeSchemeId=el.value;selection=[];isolatedGroup=null;overlay=null;markChanged();renderAll();return;}
 if(el.id==='auto-walls')mutate((_,s,g)=>g.automaticWalls=el.checked);
 if(el.id==='grid-toggle'){grid=el.checked;renderCanvas(false);}if(el.id==='snap-toggle')snapping=el.checked;
 if(el.id==='cutaway-toggle'){three.cutaway=el.checked;three.applyMode();}
 if(el.id==='jump-room'&&el.value)three?.jump(el.value);
 if(el.id==='background-opacity')mutate((_,s,g)=>g.backgroundPlan.opacity=Number(el.value));
 if(el.dataset.ruleToggle)mutate((_,s)=>s.rules.find(r=>r.id===el.dataset.ruleToggle).enabled=el.checked);
 if(el.dataset.selectId){const id=el.dataset.selectId,kind=el.dataset.selectKind;select(kind,id,true);}
}));
document.addEventListener('input',e=>{if(e.target.id==='furniture-search'){const query=e.target.value.toLocaleLowerCase();document.querySelectorAll('.catalog-card').forEach(c=>c.hidden=!c.dataset.search.toLocaleLowerCase().includes(query));}});
window.addEventListener('keydown',guarded(async e=>{
 if(e.key==='Escape'){if($('#dialog').open)return;if(three?.walking){three.exit();renderAll(false);}else if(editBase)pointerEdit('cancel');else{recognizeAfterCalibration=false;tool='select';drawPoints=[];isolatedGroup=null;selection=[];renderAll(false);}return;}
 if(e.target.closest('input:not([type=checkbox]),textarea,select,[contenteditable]')||$('#dialog').open||three?.walking)return;
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();actions[e.shiftKey?'redo':'undo']();}
 else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveNow();}
 else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();actions.duplicate();}
 else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();actions['delete-selection']();}
 else if(e.key.toLowerCase()==='r'&&selectedItems().length){e.preventDefault();actions.rotate();}
 else if(e.key==='Home'){e.preventDefault();actions.fit();}
 else if(e.key==='Enter'&&tool==='draw')finishDrawing();
 else if(e.key.startsWith('Arrow')&&selection.length){e.preventDefault();const step=e.shiftKey?10:1;pointerEdit('begin');const old=snapping;snapping=false;pointerEdit('preview',{dx:e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,dy:e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0});pointerEdit('commit');snapping=old;}
}));
$('#walk-controls').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-move]');if(!b||!three)return;b.setPointerCapture(e.pointerId);three.input={forward:b.dataset.move==='forward'?1:b.dataset.move==='backward'?-1:0,right:b.dataset.move==='right'?1:b.dataset.move==='left'?-1:0};});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('#walk-controls').addEventListener(ev,()=>{if(three)three.input={forward:0,right:0};});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);saveNow();});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNow();});window.addEventListener('beforeunload',e=>{if(saveStatus!=='saved'){e.preventDefault();e.returnValue='';}});
async function start(){try{store=await openDatabase();const [projects,templates,meta]=await Promise.all([store.all('projects'),store.all('templates'),store.all('meta')]);personalTemplates=templates;for(const p of projects)try{projectCache.set(p.id,validateProject(p));}catch{toast(T.invalidFile);}project=projectCache.get(meta.find(m=>m.id==='last-project')?.projectId)??projectCache.values().next().value;
 }catch(e){toast(T.storageUnavailable);}if(!project){project=exampleProject('solo');projectCache.set(project.id,clone(project));await saveNow();}renderAll();plan.fit();}
Object.defineProperty(window,'__qijian',{get:()=>({project:clone(project),selection:clone(selection),mode,saveStatus,walking:three?.walking??false,player:three?clone(three.player):null,camera:three?{position:three.camera.position.toArray(),fov:three.camera.fov,aspect:three.camera.aspect}:null,view:clone(plan.view)})});
await start();
